{
  "name": "奥林巴斯 IX/BX 显微镜机身",
  "name_en": "Olympus IX/BX microscope body",
  "manufacturer": "Olympus",
  "description": "奥林巴斯 IX/BX 系列研究级显微镜机身，可管理照明状态并控制物镜/对焦机构的 Z 轴运动与限位，用于实验室样品观察、对焦和显微成像。",
  "description_en": "A research-grade Olympus IX/BX microscope body that manages illumination status and controls objective/focus Z-axis motion and limits for laboratory sample observation, focusing, and microscopy imaging.",
  "tag_hints": [
    "microscope body",
    "motorized focus",
    "Z-axis positioning",
    "optical microscopy",
    "objective positioning",
    "lamp status",
    "laboratory imaging"
  ],
  "actions": [
    {
      "action_name": "auto-init_origin",
      "description": "初始化运动原点参考。",
      "description_en": "Initialize the motion origin reference."
    },
    {
      "action_name": "auto-lamp_status",
      "description": "获取照明灯状态。",
      "description_en": "Get the lamp status."
    },
    {
      "action_name": "auto-move_relative_async",
      "description": "异步执行相对位移移动。",
      "description_en": "Start a relative movement asynchronously."
    },
    {
      "action_name": "auto-query",
      "description": "发送设备查询命令并读取响应。",
      "description_en": "Send a device query command and read the response."
    },
    {
      "action_name": "auto-stop",
      "description": "停止当前运动。",
      "description_en": "Stop the current motion."
    },
    {
      "action_name": "auto-idn",
      "description": "获取显微镜身份识别信息。",
      "description_en": "Get the microscope identification information."
    },
    {
      "action_name": "auto-soft_limits",
      "description": "获取或设置软件行程限位。",
      "description_en": "Get or set the software travel limits."
    },
    {
      "action_name": "auto-movement_status",
      "description": "获取运动状态。",
      "description_en": "Get the movement status."
    },
    {
      "action_name": "auto-move_relative",
      "description": "按给定距离执行相对位移移动。",
      "description_en": "Move by a specified relative distance."
    },
    {
      "action_name": "auto-z",
      "description": "获取或设置物镜 Z 轴位置。",
      "description_en": "Get or set the objective Z position."
    }
  ]
}

